require_once __DIR__.'/SecretCipher.php';
require_once __DIR__.'/OrderMail.php';
require_once __DIR__.'/SepaySettings.php';
require_once __DIR__.'/SepayCardSettings.php';
final class PaymentSettings
{
    public function __construct(private PDO $db,private array $env=[]){}
    public static function defaults():array{return ['version'=>0,'paypalEnabled'=>false,'paypalClientId'=>'','paypalWebhookId'=>'','paypalRate'=>25000,'mode'=>'TEST','vnpayEnabled'=>false,'vnpayCardEnabled'=>false,'tmnCode'=>'','sepayEnabled'=>false,'sepayAuth'=>'API_KEY','sepayOauthClientId'=>'','bankCode'=>'','accountNumber'=>'','accountName'=>'','sepayCardEnabled'=>false,'sepayMerchantId'=>''];}
    public function config():array{$s=$this->db->query("SELECT data,version FROM jingo_settings WHERE id='payments'");$r=$s->fetch(PDO::FETCH_ASSOC);return $r?array_replace(self::defaults(),json_decode($r['data'],true,512,JSON_THROW_ON_ERROR),['version'=>(int)$r['version']]):self::defaults();}
    public function view():array{$c=$this->config();$configured=!empty($c['vnpayEncrypted']);$sepayKeyConfigured=!empty($c['sepayEncrypted']);$sepayHmacConfigured=!empty($c['sepayHmacEncrypted']);$sepayOauthConfigured=!empty($c['sepayOauthEncrypted']);$cardSecret=!empty($c['sepayCardEncrypted']);$cardIpn=!empty($c['sepayCardIpnEncrypted']);foreach(['paypalEncrypted','vnpayEncrypted','sepayEncrypted','sepayHmacEncrypted','sepayCardEncrypted','sepayCardIpnEncrypted','sepayOauthEncrypted'] as $field)unset($c[$field]);return array_intersect_key($c,self::defaults())+['sepayCardSecretConfigured'=>$cardSecret,'sepayCardIpnKeyConfigured'=>$cardIpn,'sepayCardIpnPath'=>'/api/v1/payments/sepay/card-ipn','vnpaySecretConfigured'=>$configured,'sepayKeyConfigured'=>$sepayKeyConfigured,'sepayHmacConfigured'=>$sepayHmacConfigured,'sepayOauthConfigured'=>$sepayOauthConfigured,'sepayTokenPath'=>'/api/v1/payments/sepay/oauth/token','sepayPath'=>'/api/v1/payments/sepay/webhook','ipnPath'=>'/api/v1/payments/vnpay/ipn','returnPath'=>'/api/v1/payments/vnpay/return'];}
    public function base():string{$base=$this->env['PUBLIC_BASE_URL']??(getenv('PUBLIC_BASE_URL')?:'');$u=parse_url($base);if(!$u||!isset($u['scheme'],$u['host'])||!in_array($u['scheme'],['http','https'],true)||isset($u['user'])||isset($u['pass'])||isset($u['query'])||isset($u['fragment']))throw new HttpError(503,'Cấu hình PUBLIC_BASE_URL hợp lệ trước khi dùng cổng thanh toán.');return $u['scheme'].'://'.$u['host'].(isset($u['port'])?':'.$u['port']:'');}
    public function save(array $in,string $actor):array
    {
        if(array_diff(array_keys($in),['version','mode','vnpayEnabled','vnpayCardEnabled','tmnCode','vnpaySecret','sepayEnabled','sepayAuth','bankCode','accountNumber','accountName','sepayKey','sepayHmacSecret','sepayOauthClientId','sepayOauthSecret','sepayCardEnabled','sepayMerchantId','sepayCardSecret','sepayCardIpnKey'])||!is_int($in['version']??null)||$in['version']<0||$in['version']>2147483646||!in_array($in['mode']??null,['TEST','LIVE'],true)||!is_bool($in['vnpayEnabled']??null)||isset($in['vnpayCardEnabled'])&&!is_bool($in['vnpayCardEnabled'])||array_key_exists('vnpayCardEnabled',$in)&&$in['vnpayCardEnabled']===null||!is_string($in['tmnCode']??null)||!preg_match('/^[A-Za-z0-9]{0,32}$/D',trim($in['tmnCode']))||array_key_exists('vnpaySecret',$in)&&!is_string($in['vnpaySecret']))throw new HttpError(400,'Kiểm tra cấu hình VNPAY.');$secret=preg_replace('/^[\s\x{FEFF}]+|[\s\x{FEFF}]+$/u','',$in['vnpaySecret']??'')??'';$length=intdiv(strlen(mb_convert_encoding($secret,'UTF-16LE','UTF-8')),2);if($length>256||$secret!==''&&$length<16||preg_match('/[\x00-\x1f\x7f]/',$secret))throw new HttpError(400,'HashSecret VNPAY từ 16 đến 256 ký tự; để trống để giữ khóa cũ.');$in=SepayCardSettings::validate(SepaySettings::validate($in));$this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{if(!$this->db->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog' FOR UPDATE")->fetchColumn())throw new HttpError(503,'Chưa cài khóa danh mục.');$old=$this->config();if($old['version']!==$in['version'])throw new HttpError(409,'Cấu hình đã thay đổi. Tải lại.');$changing=$old['mode']!==$in['mode'];$cipher=new SecretCipher(OrderMail::directory());if($changing&&$in['vnpayEnabled']&&$secret==='')throw new HttpError(400,'Đổi môi trường cần nhập lại HashSecret của cổng đang bật.');if($changing&&$secret!==''&&!empty($old['vnpayEncrypted'])&&hash_equals($cipher->decrypt($old['vnpayEncrypted']),$secret))throw new HttpError(400,'TEST và LIVE phải dùng khóa khác nhau.');$data=array_replace($old,['version'=>$in['version'],'mode'=>$in['mode'],'vnpayEnabled'=>$in['vnpayEnabled'],'vnpayCardEnabled'=>$in['vnpayCardEnabled']??$old['vnpayCardEnabled'],'tmnCode'=>trim($in['tmnCode'])]);if($changing)foreach(['vnpayEncrypted','paypalEncrypted','sepayEncrypted','sepayHmacEncrypted','sepayCardEncrypted','sepayCardIpnEncrypted','sepayOauthEncrypted'] as $key)unset($data[$key]);if($secret!=='')$data['vnpayEncrypted']=$cipher->encrypt($secret);if($data['vnpayCardEnabled']&&!$data['vnpayEnabled'])throw new HttpError(400,'Bật VNPAY trước khi bật thẻ quốc tế.');if($data['vnpayEnabled']&&($data['tmnCode']===''||empty($data['vnpayEncrypted'])))throw new HttpError(400,'VNPAY cần TmnCode và HashSecret.');$data=SepaySettings::apply($data,$old,$in,$changing,$cipher);$data=SepayCardSettings::apply($data,$old,$in,$changing,$cipher);if($data['mode']==='LIVE'&&($data['vnpayEnabled']||$data['sepayEnabled']||$data['sepayCardEnabled'])&&!str_starts_with($this->base(),'https://'))throw new HttpError(400,'LIVE cần PUBLIC_BASE_URL HTTPS.');$s=$this->db->prepare("INSERT INTO jingo_settings(id,data,version) VALUES ('payments',?,?) ON DUPLICATE KEY UPDATE data=VALUES(data),version=VALUES(version)");$s->execute([json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$in['version']+1]);$s=$this->db->prepare('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)');$s->execute([bin2hex(random_bytes(16)),$actor,'payments.settings','payments']);$this->db->commit();return $this->view();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
}
